select
	it.Cod_Produto,
	venda_liq = format(sum(it.Vlr_LiqVenIte), 'c', 'pt-br'),
	venda_bruta = format(sum(it.Vlr_BruItem), 'c', 'pt-br')
	from NFSIT IT
		INNER JOIN NFSCB CB ON IT.Cod_Estabe = CB.Cod_Estabe and IT.Ser_Nota = CB.Ser_Nota and IT.Num_Nota = CB.Num_Nota 
WHERE IT.COD_ESTABE = 1
	AND IT.Id_PolCom = 3014
	AND Dat_Emissao >= '20230401'
	AND Dat_Emissao <= '20230930'
